// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.screensimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Addimport androidx.compose.material3.Iconimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Switchimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.vector.ImageVectorimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.components.GlassPanel/** * Skill summary — id, displayName, category, icon, onClick. */data class SkillSummary(    val id: String,    val displayName: String,    val category: SkillCategory,    val icon: ImageVector? = null,    val lastInvoked: String? = null,)enum class SkillCategory(val label: String) {    System("System"),    Connectivity("Connectivity"),    Productivity("Productivity"),    Automation("Automation"),    Web("Web"),}/** * Automation rule summary. */data class AutomationRuleSummary(    val id: String,    val name: String,    val triggerDescription: String,    val actionDescription: String,    val enabled: Boolean,)/** * Skills & Automation screen. * * @param skills list of all available skills (from SkillRegistry) * @param automationRules list of automation rules (from AutomationEngine) * @param onSkillClick callback when a skill is tapped * @param onCreateAutomation callback when "Create New Automation" tapped * @param onToggleAutomation callback to enable/disable a rule */@Composablefun SkillsScreen(    skills: List<SkillSummary>,    automationRules: List<AutomationRuleSummary>,    onSkillClick: (SkillSummary) -> Unit,    onCreateAutomation: () -> Unit,    onToggleAutomation: (AutomationRuleSummary) -> Unit,    modifier: Modifier = Modifier,) {    LazyColumn(        modifier = modifier            .fillMaxSize()            .background(MaterialTheme.colorScheme.background),        contentPadding = androidx.compose.foundation.layout.PaddingValues(16.dp),        verticalArrangement = Arrangement.spacedBy(16.dp),    ) {        item {            Text(                text = "Skills & Automation",                style = MaterialTheme.typography.headlineLarge,                fontWeight = FontWeight.Bold,                color = MaterialTheme.colorScheme.onBackground,            )        }        // Skills grouped by category        val categories = skills.groupBy { it.category }        categories.forEach { (category, categorySkills) ->            item {                GlassPanel(title = "${category.label} Skills (${categorySkills.size})") {                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {                        categorySkills.forEach { skill ->                            SkillRow(skill = skill, onClick = { onSkillClick(skill) })                        }                    }                }            }        }        // Automation rules        item {            GlassPanel(title = "Automations (${automationRules.size})") {                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {                    if (automationRules.isEmpty()) {                        Text(                            text = "No automation rules yet. Create one to automate repetitive tasks.",                            style = MaterialTheme.typography.bodyMedium,                            color = MaterialTheme.colorScheme.onSurfaceVariant,                        )                    } else {                        automationRules.forEach { rule ->                            AutomationRuleRow(                                rule = rule,                                onToggle = { onToggleAutomation(rule) },                            )                        }                    }                    Spacer(modifier = Modifier.size(8.dp))                    Row(                        modifier = Modifier                            .fillMaxWidth()                            .clickable(onClick = onCreateAutomation)                            .background(                                color = MaterialTheme.colorScheme.primary.copy(alpha = 0.1f),                                shape = RoundedCornerShape(12.dp),                            )                            .padding(12.dp),                        verticalAlignment = Alignment.CenterVertically,                        horizontalArrangement = Arrangement.Center,                    ) {                        Icon(                            imageVector = Icons.Default.Add,                            contentDescription = null,                            tint = MaterialTheme.colorScheme.primary,                            modifier = Modifier.size(20.dp),                        )                        Spacer(modifier = Modifier.size(8.dp))                        Text(                            text = "Create New Automation",                            style = MaterialTheme.typography.labelLarge,                            color = MaterialTheme.colorScheme.primary,                            fontWeight = FontWeight.SemiBold,                        )                    }                }            }        }    }}@Composableprivate fun SkillRow(    skill: SkillSummary,    onClick: () -> Unit,) {    Row(        modifier = Modifier            .fillMaxWidth()            .clickable(onClick = onClick)            .padding(vertical = 8.dp),        verticalAlignment = Alignment.CenterVertically,    ) {        if (skill.icon != null) {            Icon(                imageVector = skill.icon,                contentDescription = null,                tint = MaterialTheme.colorScheme.primary,                modifier = Modifier.size(20.dp),            )            Spacer(modifier = Modifier.size(12.dp))        }        Column(modifier = Modifier.weight(1f)) {            Text(                text = skill.displayName,                style = MaterialTheme.typography.bodyMedium,                color = MaterialTheme.colorScheme.onSurface,            )            if (skill.lastInvoked != null) {                Text(                    text = "Last used: ${skill.lastInvoked}",                    style = MaterialTheme.typography.labelSmall,                    color = MaterialTheme.colorScheme.onSurfaceVariant,                )            }        }    }}@Composableprivate fun AutomationRuleRow(    rule: AutomationRuleSummary,    onToggle: () -> Unit,) {    Row(        modifier = Modifier            .fillMaxWidth()            .padding(vertical = 8.dp),        verticalAlignment = Alignment.CenterVertically,    ) {        Column(modifier = Modifier.weight(1f)) {            Text(                text = rule.name,                style = MaterialTheme.typography.bodyMedium,                fontWeight = FontWeight.SemiBold,                color = MaterialTheme.colorScheme.onSurface,            )            Text(                text = "Trigger: ${rule.triggerDescription}",                style = MaterialTheme.typography.labelSmall,                color = MaterialTheme.colorScheme.onSurfaceVariant,            )            Text(                text = "Action: ${rule.actionDescription}",                style = MaterialTheme.typography.labelSmall,                color = MaterialTheme.colorScheme.onSurfaceVariant,            )        }        Spacer(modifier = Modifier.size(8.dp))        Switch(            checked = rule.enabled,            onCheckedChange = { onToggle() },        )    }}